import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.cZsgxozV.js";var i=JSON.parse(`{"title":"Mermaid size (<!-- mermaid-size … -->)","description":"","frontmatter":{},"headers":[],"relativePath":"custom-markdown/mermaid-size.md","filePath":"custom-markdown/mermaid-size.md"}`),a={name:`custom-markdown/mermaid-size.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n('<h1 id="mermaid-size-mermaid-size" tabindex="-1">Mermaid size (<code>&lt;!-- mermaid-size … --&gt;</code>) <a class="header-anchor" href="#mermaid-size-mermaid-size" aria-label="Permalink to “Mermaid size (&lt;!-- mermaid-size … --&gt;)”">​</a></h1><p>PDF export에서 Mermaid 다이어그램 크기를 조절하면 fence 본문은 그대로 두고, 바로 위 HTML 주석에 크기가 저장된다. 문서를 다시 PDF로내면 주석이 파싱되어 동일한 크기가 적용된다.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to “Syntax”">​</a></h2><div class="language-markdown"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">&lt;!-- mermaid-size width=&quot;420px&quot; height=&quot;280px&quot; --&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```mermaid</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A --&gt; B</span></span></code></pre></div><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>\n<span class="line"><span>- 주석은 대상 ```mermaid fence **바로 앞**에 둔다 (사이에 빈 줄만 허용).</span></span>\n<span class="line"><span>- `width` / `height` (또는 `w` / `h`) 중 하나 이상 필수.</span></span>\n<span class="line"><span>- Size value 규칙은 [index.md](./index.md) shared conventions과 같다.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>레거시 fence info (` ```mermaid width=… height=…`)도 읽을 수 있으나, PDF export UI에서 저장할 때는 **주석이 canonical** 이다 (fence info의 size 키는 제거).</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## Spec (interop)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>기준 구현: `mermaidSizeComment.ts`, `mermaidFenceMarkdownIt.ts`.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 1. Grammar</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```text</span></span>\n<span class="line"><span>MERMAID_SIZE := &quot;&lt;!--&quot; WS &quot;mermaid-size&quot; WS ATTRS &quot;--&gt;&quot;</span></span>\n<span class="line"><span>ATTRS        := ( WS KEY &quot;=&quot; &#39;&quot;&#39; VALUE &#39;&quot;&#39; )*</span></span>\n<span class="line"><span>KEY          := width | height | w | h</span></span></code></pre></div><h3 id="_2-placement" tabindex="-1">2. Placement <a class="header-anchor" href="#_2-placement" aria-label="Permalink to “2. Placement”">​</a></h3><p>Immediately before one ```mermaid fence (0-based occurrence among all mermaid fences in document order). Optional blank lines between comment and fence.</p><h3 id="_3-parse-algorithm" tabindex="-1">3. Parse algorithm <a class="header-anchor" href="#_3-parse-algorithm" aria-label="Permalink to “3. Parse algorithm”">​</a></h3><ol><li>When rendering a mermaid fence at source line <code>L</code>, scan lines <code>L-1, L-2, …</code> skipping blank lines.</li><li>First non-blank line must match <code>&lt;!-- mermaid-size … --&gt;</code> or stop (no sidecar).</li><li>Parse attrs; normalize size values (<code>normalizeSizeValue</code>).</li><li>Merge with fence info: <strong>comment wins</strong> per dimension; fence info fills missing dimensions.</li></ol><h3 id="_4-canonical-html" tabindex="-1">4. Canonical HTML <a class="header-anchor" href="#_4-canonical-html" aria-label="Permalink to “4. Canonical HTML”">​</a></h3><p>Same as <a href="./mermaid-fence-size.html">mermaid-fence-size.md</a>: <code>data-mermaid-width</code>, <code>data-mermaid-height</code>, <code>data-mermaid-sized=&quot;1&quot;</code>, inline <code>style</code>.</p><h3 id="_5-update-algorithm-export-pdf-free-transform" tabindex="-1">5. Update algorithm (Export PDF free-transform) <a class="header-anchor" href="#_5-update-algorithm-export-pdf-free-transform" aria-label="Permalink to “5. Update algorithm (Export PDF free-transform)”">​</a></h3><p>Given 0-based mermaid occurrence:</p><ol><li>Strip <code>width</code>/<code>height</code> from fence open line (plain <code> ```mermaid</code>).</li><li>Insert or replace preceding <code>&lt;!-- mermaid-size … --&gt;</code> with new dimensions.</li><li>Omit comment when both dimensions cleared.</li></ol><h3 id="_6-non-goals" tabindex="-1">6. Non-goals <a class="header-anchor" href="#_6-non-goals" aria-label="Permalink to “6. Non-goals”">​</a></h3><ul><li>Rotating / skew transforms</li><li>Size on non-mermaid fences (except shared host attrs for base64 embeds)</li></ul><h2 id="구현" tabindex="-1">구현 <a class="header-anchor" href="#구현" aria-label="Permalink to “구현”">​</a></h2><table tabindex="0"><thead><tr><th>역할</th><th>경로</th></tr></thead><tbody><tr><td>parse / upsert markdown</td><td><code>src/utils/mermaidSizeComment.ts</code></td></tr><tr><td>markdown-it fence merge</td><td><code>src/utils/mermaidFenceMarkdownIt.ts</code></td></tr><tr><td>Export PDF free-transform save</td><td><code>src/pages/exportPdf/hooks/useExportPdfImageInteractions.ts</code></td></tr><tr><td>Lazy render attr copy</td><td><code>src/utils/lazyMermaid.ts</code></td></tr><tr><td>Skip auto-fit when sized</td><td><code>src/hooks/usePrintMermaidFit.ts</code></td></tr></tbody></table><p>See also: <a href="./mermaid-fence-size.html">mermaid-fence-size.md</a> (legacy fence info).</p>',19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};